typedef struct {
    void *data;
    size_t size;
    void (*copy_func)(void *dest, const void *src);
} DeepCopyStruct;

// Function to perform deep copy using function pointer
void deep_copy(DeepCopyStruct *dest, const DeepCopyStruct *src) {
    dest->data = malloc(src->size);
    if (dest->data) {
        src->copy_func(dest->data, src->data);
    }
    dest->size = src->size;
    dest->copy_func = src->copy_func;
}

