typedef struct {
    char *name;
    int *values;
    size_t count;
    void (*copy_func)(void *, const void *);
} Person;

void copy_string(void *dest, const void *src) {
    strcpy((char *)dest, (const char *)src);
}

void copy_int_array(void *dest, const void *src, size_t count) {
    memcpy(dest, src, count * sizeof(int));
}

void deep_copy_person(Person *dest, const Person *src) {
    dest->name = malloc(strlen(src->name) + 1);
    src->copy_func(dest->name, src->name);
    dest->values = malloc(src->count * sizeof(int));
    copy_int_array(dest->values, src->values, src->count);
    dest->count = src->count;
    dest->copy_func = src->copy_func;
}
